import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { sheetInfoKey, sheetKey, useCurrentSheet, useCurrentUser } from './session';
import type { SheetInfo } from './session';
import { useSheetToday } from './sheetToday';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's own "today": shown, and changed by typing a date and saving. A blank date resets it
// to the real date.
export function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const [date, setDate] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}/today?user=${encodeURIComponent(user)}`, { today: value }),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetInfoKey(saved.id), saved);
      // Everything that depends on the date is kept under the sheet's key.
      await queryClient.invalidateQueries({ queryKey: sheetKey(saved.id) });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = date.trim();
    setError('');
    if (trimmed && !/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(trimmed));
  };

  return (
    <form onSubmit={submit}>
      <span>
        Today: <strong data-testid="sheet-today">{today}</strong>{' '}
      </span>
      <input
        data-testid="sheet-today-input"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today
      </button>
      {error && <span data-testid="sheet-error">{error}</span>}
    </form>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetInfoKey, useCurrentSheet } from './session';
import type { SheetInfo } from './session';

/**
 * The active sheet's today (yyyy-MM-dd), or '' while it loads. Every date-dependent decision and
 * every default date on screen uses this — never `new Date()`.
 */
export function useSheetToday(): string {
  const [sheet] = useCurrentSheet();
  const info = useQuery({
    queryKey: sheetInfoKey(sheet),
    queryFn: () => getJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}`),
    enabled: !!sheet,
  });
  return info.data?.today ?? '';
}
import { AppHeader } from '../../slots/defs/appHeader';
import { SheetPicker } from './SheetPicker';
import { SheetToday } from './SheetToday';
import { SignIn } from './SignIn';

export const contributions = [
  AppHeader.fill({ order: 0, Component: SignIn }),
  AppHeader.fill({ order: 10, Component: SheetPicker }),
  AppHeader.fill({ order: 20, Component: SheetToday }),
];
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { usePeople } from '../people/people';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { claimsKey, useClaims } from './claims';
import type { Claim } from './claims';
import { useSelectedClaims } from './selection';
import { useOneAtATime } from '../../query/useOneAtATime';

// Opens every ticked claim, one after another in list order (people in their order, each one's
// claims newest first), so they are numbered in that order. Each goes through the claim's own open
// action: one the server refuses is left as it is and counted as refused.
export function BulkOpen() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const [selected, , clear] = useSelectedClaims();
  const [result, setResult] = useState<{ opened: number; refused: number } | undefined>(undefined);
  const [busy, setBusy] = useState(false);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  if (!user || !sheet) return null;

  const run = async () => {
    setResult(undefined);
    setBusy(true);
    const ordered = people.flatMap((p) => claims.filter((c) => c.personId === p.id && selected.has(c.id)));
    let opened = 0;
    let refused = 0;
    try {
      for (const c of ordered) {
        try {
          await postJson<Claim>(
            `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/open?user=${encodeURIComponent(user)}`,
            {},
          );
          opened++;
        } catch {
          refused++;
        }
      }
      // A ticked claim no longer listed (gone from the sheet) cannot be opened.
      refused += selected.size - ordered.length;
      clear();
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    } finally {
      setBusy(false);
      setResult({ opened, refused });
    }
  };

  return (
    <p>
      <button type="button" data-testid="bulk-open" disabled={busy} onClick={() => once(run)}>
        Open selected claims
      </button>
      {result && (
        <>
          {' '}
          Opened <span data-testid="bulk-opened">{result.opened}</span>, refused{' '}
          <span data-testid="bulk-refused">{result.refused}</span>
        </>
      )}
    </p>
  );
}

